<template><sf-modal :open="open" :title="title" :label="title" presentation="dialog" :contained="contained" :busy="busy" :dismissible="dismissible" initial-focus=".sf-dialog-cancel" :alert="true" @input="$emit('input',$event)" @close="$emit('close',$event)" @dismiss-blocked="$emit('dismiss-blocked',$event)"><p v-if="description">{{ description }}</p><slot/><template #footer><div class="sf-dialog-actions"><button type="button" class="sf-dialog-cancel" :disabled="busy" @click="cancel">{{ cancelLabel }}</button><button type="button" :class="{'is-destructive':destructive}" :disabled="busy" @click="$emit('confirm')">{{ confirmLabel }}</button></div></template></sf-modal></template>
<script>import SfModal from './SfModal';export default {name:'SfDialog',components:{SfModal},model:{prop:'open',event:'input'},props:{open:Boolean,title:{type:String,required:true},description:String,cancelLabel:{type:String,default:'Cancel'},confirmLabel:{type:String,default:'Confirm'},destructive:Boolean,contained:Boolean,busy:Boolean,dismissible:{type:Boolean,default:true}},methods:{cancel(){if(this.busy)return;this.$emit('input',false);this.$emit('close','cancel')}}}</script>
